public class GTreeRenderer : DefaultTreeCellRenderer, GComponent {

	private static readonly Color VALID_DROP_TARGET_COLOR = new GColor("color.bg.tree.drag");
	private static readonly int DEFAULT_MIN_ICON_WIDTH = 22;
	private static readonly Color BACKGROUND_UNSELECTED = new GColor("color.bg.tree");
	private static readonly Color BACKGROUND_SELECTED = new GColor("color.bg.tree.selected");
	private static readonly Color FOREGROUND_SELECTED = new GColor("color.fg.tree.selected");

	private object dropTarget;
	private bool paintDropTarget;

	private Font cachedDefaultFont;
	private Font cachedBoldFont;
	private int minIconWidth = DEFAULT_MIN_ICON_WIDTH;

	public GTreeRenderer() {
		setHTMLRenderingEnabled(false);
		setBackgroundNonSelectionColor(BACKGROUND_UNSELECTED);
		setBackgroundSelectionColor(BACKGROUND_SELECTED);
		setTextSelectionColor(FOREGROUND_SELECTED);
	}

	/* @Override */
	public Component getTreeCellRendererComponent(JTree tree, object value, bool selected1,
			bool expanded, bool leaf, int row, bool hasFocus1) {

		base.getTreeCellRendererComponent(tree, value, selected1, expanded, leaf, row, hasFocus1);

		// Important - make sure this happens before the setBackground() call, otherwise we will
		//             paint the previously dragged-over node as the drop target.
		paintDropTarget = (value == dropTarget);

		setBackground(selected1 ? getBackgroundSelectionColor() : getBackgroundNonSelectionColor());

		if (!(value is GTreeNode)) {
			// not a GTree
			return this;
		}

		GTreeNode node = (GTreeNode) value;
		string text = node.getDisplayText();
		setText(text);

		string toolTip = node.getToolTip();
		setToolTipText(toolTip);

		// Note: attempting to use the tooltip text here by removing the html formatting can be 
		// too slow for large functions.  Also, the full preview text for larger symbol tool tips
		// can be overwhelming for screen readers.   The text of the node is a reasonable value 
		// to provide for screen readers.
		// String fromHTML = HTMLUtilities.fromHTML(toolTip);
		getAccessibleContext().setAccessibleDescription(node.getDisplayText());

		Icon icon = getNodeIcon(node, expanded);
		if (icon == null) {
			icon = getIcon();
		}
		else {
			setIcon(icon);
		}

		updateIconTextGap(icon, minIconWidth);

		GTree gtree = node.getTree();

		GTreeFilter filter = gtree == null ? null : gtree.getFilter();
		bool isBold = (filter != null) && filter.showFilterMatches() && filter.acceptsNode(node);
		setFont(getFont(isBold));
		return this;
	}

	protected Icon getNodeIcon(GTreeNode node, bool expanded) {
		return node.getIcon(expanded);
	}

